    /// <summary>Gets the width of a character in a Helvetica or Times core font.</summary>
    internal static bool TryGetWidth1000(PdfStandardFont font, char value, out int width) {
        short[]? widths = font switch {
            PdfStandardFont.Helvetica or PdfStandardFont.HelveticaOblique => Helvetica,
            PdfStandardFont.HelveticaBold or PdfStandardFont.HelveticaBoldOblique => HelveticaBold,
            PdfStandardFont.TimesRoman => TimesRoman,
            PdfStandardFont.TimesBold => TimesBold,
            PdfStandardFont.TimesItalic => TimesItalic,
            PdfStandardFont.TimesBoldItalic => TimesBoldItalic,
            _ => null
        };
        width = 0;
        if (widths == null) return false;
        // WinAnsiEncoding paints the space and hyphen glyphs for these characters.
        if (value == '\u00A0') value = ' ';
        else if (value == '\u00AD') value = '-';
        int index = System.Array.BinarySearch(Characters, value);
        if (index < 0) return false;
        width = widths[index];
        return true;
    }
